class InMemoryFileSystem:
    def __init__(self) -> None:
        self.files: dict[str, bytes] = {}
        self.links: dict[str, str] = {}

    def exists(self, path: str) -> bool:
        return path in self.files or path in self.links

    def symlink(self, path: str, target: str) -> None:
        self.links[path] = target

    def write(self, path: str, data: bytes) -> None:
        target = self.links.get(path, path)
        self.files[target] = data

    def read(self, path: str) -> bytes:
        return self.files[self.links.get(path, path)]

    def rename(self, source: str, dest: str) -> None:
        target = self.links.get(source, source)
        self.files[dest] = self.files.pop(target)
        self.links.pop(source, None)

