"""Upload staging, scan, and commit workflow."""

from audit_log import AuditLogRecord
from filesystem import InMemoryFileSystem
from name_allocator import NameAllocatorRecord
from scanner import ScannerRecord
from upload_models import UploadRequest, UploadResponse


def stage_name(request: UploadRequest) -> str:
    safe = request.filename.replace("/", "_").replace("\\", "_")
    return f"/tmp/uploads/{request.account_id}-{safe}.part"


def final_name(request: UploadRequest) -> str:
    safe = request.filename.replace("/", "_").replace("\\", "_")
    return f"/uploads/{request.account_id}/{safe}"


def accept_upload(request: UploadRequest, fs: InMemoryFileSystem, audit: AuditLogRecord | None = None) -> dict:
    temp = stage_name(request)
    final = final_name(request)
    if not request.content_type.startswith("image/"):
        if audit is not None:
            audit.metadata.setdefault("events", []).append(("rejected", "content_type"))
        return UploadResponse(False, "rejected").as_dict()
    fs.write(temp, request.body)
    if b"virus" in fs.read(temp).lower():
        if audit is not None:
            audit.metadata.setdefault("events", []).append(("rejected", "scan"))
        return UploadResponse(False, "rejected").as_dict()
    fs.rename(temp, final)
    if audit is not None:
        audit.metadata.setdefault("events", []).append(("accepted", final))
    return UploadResponse(True, "stored", final).as_dict()

