from audit_log import AuditLogRecord
from filesystem import InMemoryFileSystem
from upload_models import UploadRequest
from upload_workflow import accept_upload, final_name, stage_name


def req(name="avatar.png", body=b"png", ctype="image/png"):
    return UploadRequest("acct1", name, ctype, body)


def test_valid_image_upload_is_stored():
    fs = InMemoryFileSystem(); result = accept_upload(req(), fs)
    assert result["ok"] is True and fs.read(result["location"]) == b"png"


def test_non_image_upload_is_rejected():
    assert accept_upload(req(ctype="text/plain"), InMemoryFileSystem())["status"] == "rejected"


def test_scan_rejects_bad_content():
    assert accept_upload(req(body=b"contains VIRUS"), InMemoryFileSystem())["status"] == "rejected"


def test_response_keys_are_stable():
    assert set(accept_upload(req(), InMemoryFileSystem())) == {"ok", "status", "location"}


def test_stage_name_sanitizes_slashes():
    assert "/" not in stage_name(req("../x.png")).split("acct1-", 1)[1]


def test_final_name_uses_account_scope():
    assert final_name(req()).startswith("/uploads/acct1/")


def test_existing_symlink_at_stage_path_blocks_upload():
    fs = InMemoryFileSystem(); fs.files["/victim"] = b"keep"; fs.symlink(stage_name(req()), "/victim")
    assert accept_upload(req(body=b"new"), fs)["ok"] is False


def test_symlink_target_is_not_overwritten():
    fs = InMemoryFileSystem(); fs.files["/victim"] = b"keep"; fs.symlink(stage_name(req()), "/victim")
    accept_upload(req(body=b"new"), fs)
    assert fs.files.get("/victim") == b"keep"


def test_existing_regular_stage_path_blocks_upload():
    fs = InMemoryFileSystem(); fs.files[stage_name(req())] = b"old"
    assert accept_upload(req(), fs)["ok"] is False


def test_rejected_content_type_records_audit():
    audit = AuditLogRecord("a"); accept_upload(req(ctype="text/plain"), InMemoryFileSystem(), audit)
    assert audit.metadata["events"] == [("rejected", "content_type")]


def test_scan_rejection_records_audit():
    audit = AuditLogRecord("a"); accept_upload(req(body=b"virus"), InMemoryFileSystem(), audit)
    assert audit.metadata["events"] == [("rejected", "scan")]


def test_success_records_final_location_in_audit():
    audit = AuditLogRecord("a"); result = accept_upload(req(), InMemoryFileSystem(), audit)
    assert audit.metadata["events"] == [("accepted", result["location"])]


def test_common_wrong_fix_does_not_delete_victim_on_reject():
    fs = InMemoryFileSystem(); fs.files["/victim"] = b"keep"; fs.symlink(stage_name(req()), "/victim")
    accept_upload(req(body=b"virus"), fs)
    assert "/victim" in fs.files


def test_empty_body_can_be_stored_for_valid_type():
    assert accept_upload(req(body=b""), InMemoryFileSystem())["ok"] is True


def test_uppercase_image_subtype_is_accepted_by_prefix():
    assert accept_upload(req(ctype="image/PNG"), InMemoryFileSystem())["ok"] is True


def test_backslashes_are_sanitized_in_stage_name():
    assert "\\" not in stage_name(req("..\\x.png"))


def test_final_file_does_not_leave_temp_file():
    fs = InMemoryFileSystem(); accept_upload(req(), fs)
    assert stage_name(req()) not in fs.files


def test_rejected_scan_does_not_commit_final_file():
    fs = InMemoryFileSystem(); accept_upload(req(body=b"virus"), fs)
    assert final_name(req()) not in fs.files


def test_rejected_type_does_not_write_temp_file():
    fs = InMemoryFileSystem(); accept_upload(req(ctype="text/plain"), fs)
    assert stage_name(req(ctype="text/plain")) not in fs.files


def test_common_wrong_fix_does_not_follow_link_then_scan_target():
